const allowed = ($env.TELEGRAM_ALLOWED_CHAT_IDS || '').split(',').map(s => s.trim()).filter(Boolean);
const msg = $input.first().json.message || {};
const chatId = msg.chat ? msg.chat.id : null;
const text = msg.text || '';
if (!chatId || !text) return [];
if (allowed.length && !allowed.includes(String(chatId))) return [];
return [{ json: { chat_id: chatId, prompt: 'أنت رئيس المكتب الرقمي (Chief of Staff). التزم بسلم الاستقلالية: لا تنفذ أي إجراء مالي أو خارجي دون اعتماد بشري صريح. كن موجزاً واستخدم النقاط.\nرسالة المستخدم: ' + text } }];

const resp = $input.first().json;
const text = (resp.candidates && resp.candidates[0] && resp.candidates[0].content && resp.candidates[0].content.parts && resp.candidates[0].content.parts[0] && resp.candidates[0].content.parts[0].text) || 'عذراً، تعذر توليد الرد الآن.';
return [{ json: { chat_id: $('Auth & Prompt').first().json.chat_id, text } }];
